INSERT INTO `knowledge_chunk` (`id`, `document_id`, `article`, `section`, `page`, `sequence`, `text`) VALUES
  ('tentang-nemu-document', 'tentang-nemu', NULL, 'Tentang Nemu', NULL, 0, '# Tentang Nemu

Panduan bawaan AlurSekolah tentang Nemu, untuk guru.'),
  ('tentang-nemu-pasal-1.1', 'tentang-nemu', '1.1', NULL, NULL, 1, '1. Apa itu Nemu
1.1 Nemu adalah pendamping administrasi guru di AlurSekolah. Nemu bisa diajak bicara atau diberi pertanyaan tertulis.'),
  ('tentang-nemu-pasal-1.2', 'tentang-nemu', '1.2', NULL, NULL, 2, '1.2 Nemu menjawab aturan dan prosedur hanya dari panduan sekolah yang aktif. Kalau jawabannya belum ada di panduan, Nemu memberi tahu dan tidak menebak.'),
  ('tentang-nemu-pasal-2.1', 'tentang-nemu', '2.1', NULL, NULL, 3, '2. Yang Nemu ketahui dan bisa bantu
2.1 Nemu mengetahui isi panduan sekolah yang diunggah operator: SOP, alur proses sekolah, dan Kamus Kendala. Dengan itu Nemu bisa membantu Anda mengisi nilai, menjawab pertanyaan tentang aturan sekolah, menjelaskan pesan error, menuntun langkah prosedur, dan memeriksa kuis Moodle.'),
  ('tentang-nemu-pasal-2.2', 'tentang-nemu', '2.2', NULL, NULL, 4, '2.2 Mengisi nilai: kirim foto buku nilai ke WhatsApp Nemu, lalu katakan nilai apa yang mau dimasukkan. Nemu membaca foto dan mengisinya di AlurSekolah, lalu Anda sendiri yang menekan Simpan.'),
  ('tentang-nemu-pasal-2.3', 'tentang-nemu', '2.3', NULL, NULL, 5, '2.3 Bertanya aturan: tanyakan aturan atau prosedur sekolah. Nemu menjawab dari panduan sekolah dan menunjukkan sumbernya.'),
  ('tentang-nemu-pasal-2.4', 'tentang-nemu', '2.4', NULL, NULL, 6, '2.4 Menjelaskan error: tanyakan "ini kenapa?" saat muncul pesan error atau nilai tidak muncul. Nemu menjelaskan penyebabnya dan siapa yang bisa membantu.'),
  ('tentang-nemu-pasal-2.5', 'tentang-nemu', '2.5', NULL, NULL, 7, '2.5 Menuntun prosedur: sebutkan nama prosedurnya, misalnya pengajuan izin guru. Nemu menunjukkan langkahnya satu per satu.'),
  ('tentang-nemu-pasal-2.6', 'tentang-nemu', '2.6', NULL, NULL, 8, '2.6 Kuis Moodle: Nemu bisa memasang soal dari naskah ke Moodle dan memeriksa kuis seperti yang dilihat siswa. Nemu tidak menghapus kuis.'),
  ('tentang-nemu-pasal-3.1', 'tentang-nemu', '3.1', NULL, NULL, 9, '3. Bicara dengan Nemu
3.1 Tahan tombol Nemu di pojok layar, atau tombol pintasannya di keyboard, sambil bicara, lalu lepaskan. Pertanyaan juga bisa diketik di kotak Tanya Nemu.'),
  ('tentang-nemu-pasal-3.2', 'tentang-nemu', '3.2', NULL, NULL, 10, '3.2 Ucapkan "berhenti" untuk menghentikan Nemu, "ulangi" untuk mendengar lagi, atau "pelan" supaya Nemu bicara lebih pelan.'),
  ('tentang-nemu-pasal-4.1', 'tentang-nemu', '4.1', NULL, NULL, 11, '4. Mikrofon di Chrome
4.1 Saat pertama kali bicara di sebuah situs, Chrome meminta izin mikrofon dalam kotak dekat alamat situs. Tekan Izinkan yang paling atas supaya Nemu bisa mendengar.'),
  ('tentang-nemu-pasal-4.2', 'tentang-nemu', '4.2', NULL, NULL, 12, '4.2 Kalau mikrofon diblokir, tekan ikon di kiri alamat situs, di bagian atas layar. Pada Mikrofon, pilih Izinkan atau nyalakan tombolnya. Lalu muat ulang halaman dan tahan lagi tombolnya.'),
  ('tentang-nemu-pasal-4.3', 'tentang-nemu', '4.3', NULL, NULL, 13, '4.3 Kalau Nemu tetap tidak mendengar, periksa mikrofon komputer, lalu coba lagi.'),
  ('tentang-nemu-pasal-5.1', 'tentang-nemu', '5.1', NULL, NULL, 14, '5. Bantuan
5.1 Untuk pertanyaan yang belum ada di panduan sekolah, hubungi operator sekolah.');
